#include <bits/stdc++.h>

using namespace std;

const int MAX_LIMIT = 1e6 + 7;
const int MOD_CONST = 1e9 + 7;
int p_input, k_input, cntArr[MAX_LIMIT], visitedArr[MAX_LIMIT], numArr[MAX_LIMIT];

void run_dfs(int x, int start){
    int count = 1;
    while ((long long)k_input * x % p_input != start){
        x = (long long)k_input * x % p_input;
        visitedArr[x] = 1;
        count++;
    }
    numArr[count]++;
}

bool isPrime(int x){
    for (int i = 2; i * i <= x; i++)
        if (x % i == 0) return false;
    return true;
}

vector<int> divisors_list;

int main(){
    scanf("%d%d", &p_input, &k_input);
    if (k_input == 0){
        long long total_product = 1;
        for (int i = 1; i < p_input; i++){
            total_product = (total_product * p_input) % MOD_CONST;
        }
        printf("%lld\n", total_product);
        return 0;
    }
    for (int i = 0; i < p_input; i++)
        if (!visitedArr[i]) run_dfs(i, i);

    for (int i = 1; i <= p_input; i++)
        if (numArr[i]) divisors_list.push_back(i);

    long long final_ans = 1;
    for (size_t i = 0; i < divisors_list.size(); i++){
        long long temp_sum = 0;
        for (size_t j = 0; j < divisors_list.size() && (long long)divisors_list[j] * divisors_list[j] <= divisors_list[i]; j++){
            if (divisors_list[i] % divisors_list[j] == 0){
                int a = divisors_list[i] / divisors_list[j];
                int b = divisors_list[j];
                temp_sum += (long long)a * numArr[a];
                if (a != b) temp_sum += (long long)b * numArr[b];
                temp_sum %= MOD_CONST;
            }
        }
        for (int j = 0; j < numArr[divisors_list[i]]; j++){
            final_ans = (final_ans * temp_sum) % MOD_CONST;
        }
    }
    printf("%lld\n", final_ans);
}
